import{_ as s,o as e,c as i,ao as t}from"./chunks/framework.CKOtou8s.js";const k=JSON.parse('{"title":"1D inversion","description":"","frontmatter":{},"headers":[],"relativePath":"inversion/1d.md","filePath":"inversion/1d.md","lastUpdated":null}'),n={name:"inversion/1d.md"};function l(h,a,o,d,p,r){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="1D-inversion" tabindex="-1">1D inversion <a class="header-anchor" href="#1D-inversion" aria-label="Permalink to &quot;1D inversion {#1D-inversion}&quot;">​</a></h1><p>A 1D inversion looks for the layered earth under one station that explains its data. It is fast and a good first look at new data: how deep the data see, and roughly what resistivities to expect. MTGeophysics.jl inverts every site of a data file on its own, with either Gauss–Newton (GN) or very fast simulated annealing (VFSA).</p><h2 id="What-you-need" tabindex="-1">What you need <a class="header-anchor" href="#What-you-need" aria-label="Permalink to &quot;What you need {#What-you-need}&quot;">​</a></h2><p>Only two files:</p><ul><li><p>the data file (the same ModEM file that 2D and 3D use)</p></li><li><p>a small control file</p></li></ul><p>Each site gets its own layering from its skin depths (see <a href="./../data/mesh2d">1D and 2D meshes</a>), and starts from a uniform earth at its median apparent resistivity.</p><h2 id="Run-the-example" tabindex="-1">Run the example <a class="header-anchor" href="#Run-the-example" aria-label="Permalink to &quot;Run the example {#Run-the-example}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpers/benchmarks_1D.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # writes examples/data/1D-I</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_inv1D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GN</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or VFSA</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_inv1D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> InvCtrl.GN</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # your own files</span></span></code></pre></div><h2 id="The-control-file" tabindex="-1">The control file <a class="header-anchor" href="#The-control-file" aria-label="Permalink to &quot;The control file {#The-control-file}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Algorithm                         : GN</span></span>
<span class="line"><span>Mode                              : XYYX</span></span>
<span class="line"><span>Exit search when rms is less than : 1</span></span>
<span class="line"><span>Maximum number of iterations      : 20</span></span>
<span class="line"><span>Initial damping factor lambda     : 1</span></span></code></pre></div><ul><li><p><code>Algorithm</code> is <code>GN</code> or <code>VFSA</code>.</p></li><li><p><code>Mode</code> chooses which impedance is fitted: <code>XY</code>, <code>YX</code>, both (<code>XYYX</code>) or the determinant (<code>DET</code>).</p></li><li><p><code>lambda</code> sets how smooth the GN model is. Larger values give smoother models.</p></li></ul><p>A VFSA control file replaces the <code>lambda</code> line with the search bounds and the number of chains:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Log10 resistivity bounds          : 0 4</span></span>
<span class="line"><span>Number of chains                  : 10</span></span></code></pre></div><h2 id="From-Julia" tabindex="-1">From Julia <a class="header-anchor" href="#From-Julia" aria-label="Permalink to &quot;From Julia {#From-Julia}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MTGeophysics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Invert1D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;InvCtrl.GN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotInversion1D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run; true_model_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;model.true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="What-you-get" tabindex="-1">What you get <a class="header-anchor" href="#What-you-get" aria-label="Permalink to &quot;What you get {#What-you-get}&quot;">​</a></h2><p>The run writes a <code>run_YYYYmmdd_HHMMSS/</code> folder next to the data. Each site has its own folder with the start and final models, the predicted data, the convergence history and <code>plots/</code>. Next to them are <code>data.pred</code> for all sites together and a <code>Summary.txt</code>.</p><div class="tip custom-block"><p class="custom-block-title">VFSA in 1D</p><p>VFSA lets every layer move freely, without smoothing. Several quite different layered models can fit the same data equally well, so the chains may disagree. The run reports the mean of the chains&#39; best models as <code>model.rho</code>, and the 5–95 % range shows how well each depth is resolved. The mean usually fits the data worse than the individual chains do; <code>Summary.txt</code> gives both.</p></div>`,18)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
